<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require_staff_or_admin($pdo);
$admin = ($_SESSION['role'] ?? '') === 'admin';
$pageTitle = $admin ? 'Admin dashboard' : 'Staff workspace';
if ($admin) {
    $news = $pdo->query("SELECT event_id,event_type,title,message,created_at FROM team_inbox_events WHERE event_type LIKE '%application%' OR event_type LIKE '%contact%' OR event_type LIKE '%feedback%' ORDER BY created_at DESC LIMIT 6")->fetchAll();
    $events = $pdo->query("SELECT event_type,title,message,created_at FROM (SELECT CONCAT('login_',l.outcome) event_type,CONCAT(COALESCE(i.first_name,'Employee'),' logged in') title,CONCAT('Successful ',COALESCE(l.purpose,'account'),' sign-in') message,l.created_at FROM auth_security_logs l LEFT JOIN user_info i ON i.user_id=l.user_id WHERE l.event_name='login' AND l.outcome='success' UNION ALL SELECT a.event_type event_type,CONCAT('Order ',o.order_number,' ',REPLACE(a.to_status,'_',' ')) title,CONCAT('Order status changed from ',REPLACE(a.from_status,'_',' '),' to ',REPLACE(a.to_status,'_',' ')) message,a.created_at FROM staff_order_actions a JOIN customer_orders o ON o.order_id=a.order_id UNION ALL SELECT event_type,title,message,created_at FROM team_inbox_events WHERE event_type LIKE '%updated%' OR event_type LIKE '%changed%') recent ORDER BY created_at DESC LIMIT 8")->fetchAll();
    $counts = ['applications'=>(int)$pdo->query("SELECT COUNT(*) FROM careers_applications WHERE status='new'")->fetchColumn(),'feedback'=>(int)$pdo->query("SELECT COUNT(*) FROM contact_submissions WHERE status='new'")->fetchColumn(),'orders'=>(int)$pdo->query("SELECT COUNT(*) FROM customer_orders WHERE created_at >= CURDATE()")->fetchColumn()];
}
require 'includes/header.php';
?>
<main class="container py-5"><div class="d-flex justify-content-between align-items-end mb-4"><div><p class="text-uppercase small fw-semibold text-secondary mb-1"><?= $admin?'Admin dashboard':'Staff workspace' ?></p><h1 class="mb-1"><?= $admin?'Good day, '.e($_SESSION['first_name']??'Admin'):'Management' ?></h1><p class="text-secondary mb-0"><?= $admin?'A quick view of what needs attention.':'Choose a tool available to your account.' ?></p></div><?php if($admin): ?><a class="btn btn-auth" href="analytics.php">View analytics <i class="bi bi-arrow-right ms-1"></i></a><?php endif; ?></div>
<?php if($admin): ?><div class="row g-3 mb-4"><?php foreach([['New applicants',$counts['applications'],'bi-person-lines-fill','team-inbox.php?tab=applications'],['New feedback',$counts['feedback'],'bi-chat-left-text','team-inbox.php?tab=feedback'],["Today's orders",$counts['orders'],'bi-receipt','analytics.php']] as [$label,$count,$icon,$url]): ?><div class="col-md-4"><a href="<?=$url?>" class="management-card"><span class="management-card-icon"><i class="bi <?=$icon?>"></i></span><h2><?=$count?></h2><p class="mb-0"><?=$label?></p></a></div><?php endforeach; ?></div><div class="row g-4"><div class="col-lg-6"><section class="card card-body h-100"><div class="d-flex justify-content-between"><h2 class="h4">Latest news</h2><a href="team-inbox.php">Team inbox</a></div><?php if(!$news): ?><p class="text-secondary">No applicant or feedback updates yet.</p><?php endif; ?><?php foreach($news as $item): ?><article class="border-top py-3"><div class="d-flex justify-content-between gap-2"><strong><?=e($item['title'])?></strong><small class="text-secondary"><?=e(date('M j, g:i A',strtotime($item['created_at'])))?></small></div><p class="mb-0 small text-secondary"><?=e($item['message'])?></p></article><?php endforeach; ?></section></div><div class="col-lg-6"><section class="card card-body h-100"><h2 class="h4">Latest events</h2><?php if(!$events): ?><p class="text-secondary">No recent order or change events yet.</p><?php endif; ?><?php foreach($events as $item): ?><article class="border-top py-3"><div class="d-flex justify-content-between gap-2"><strong><?=e($item['title'])?></strong><small class="text-secondary"><?=e(date('M j, g:i A',strtotime($item['created_at'])))?></small></div><p class="mb-0 small text-secondary"><?=e($item['message'])?></p></article><?php endforeach; ?></section></div></div><?php else: ?><div class="row g-4"><div class="col-md-6"><a class="management-card" href="staff-orders.php"><span class="management-card-icon"><i class="bi bi-receipt"></i></span><h2>Incoming orders</h2><p>Review customer orders and update their status.</p></a></div><div class="col-md-6"><a class="management-card" href="menu-management.php"><span class="management-card-icon"><i class="bi bi-card-list"></i></span><h2>Menu management</h2><p>View and update menu items.</p></a></div><div class="col-md-6"><a class="management-card" href="team-inbox.php"><span class="management-card-icon"><i class="bi bi-inbox"></i></span><h2>Team inbox</h2><p>Review applications, customer feedback, and site activity.</p></a></div></div><?php endif; ?></main><?php require 'includes/footer.php'; ?>
